class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int left = 0;
        int right = rows * cols - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            int value = matrix[mid / cols][mid % cols];
            if (value == target) {
                return true;
            }
            if (value < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return false;
    }
}

class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int left = 0;
        int right = rows * cols;

        while (left < right) {
            int mid = left + (right - left) / 2;
            int value = matrix[mid / cols][mid % cols];
            if (value < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left < rows * cols && matrix[left / cols][left % cols] == target;
    }
}

class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        int top = 0;
        int bottom = rows - 1;
        while (top < bottom) {
            int mid = top + (bottom - top + 1) / 2;
            if (matrix[mid][0] <= target) {
                top = mid;
            } else {
                bottom = mid - 1;
            }
        }

        int row = top;
        int left = 0;
        int right = cols - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (matrix[row][mid] == target) {
                return true;
            }
            if (matrix[row][mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return false;
    }
}

class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        return search(matrix, target, cols, 0, rows * cols - 1);
    }

    private boolean search(int[][] matrix, int target, int cols, int left, int right) {
        if (left > right) {
            return false;
        }

        int mid = left + (right - left) / 2;
        int value = matrix[mid / cols][mid % cols];
        if (value == target) {
            return true;
        }
        if (value < target) {
            return search(matrix, target, cols, mid + 1, right);
        }
        return search(matrix, target, cols, left, mid - 1);
    }
}
